/** Upgrade, rotation, independent icon sheets, recovery and live cross-application palettes. */
public final class TenWorkspaceSmoke extends TenThemeSmoke {
    String first,other,legacyFolder;
    @Override public void onStart(){Bundle result=new Bundle();try{
        store=new DesktopStore(getTargetContext());first="desktop-1";other="desktop-2";legacyFolder="folder:de4092e4-6334-49d7-8e62-0aa969b47e68";
        JSONObject metadata=new JSONObject().put("current",first).put("desktops",new JSONArray().put(new JSONObject().put("id",first).put("name","Desktop 1")).put(new JSONObject().put("id",other).put("name","Research")));
        JSONObject folder=new JSONObject().put("name","My preserved folder").put("items",new JSONArray().put("@browser").put("@notes"));
        store.prefs.edit().remove(TenDesktopItems.KEY).putString(TenDesktops.KEY,metadata.toString()).putString("shortcuts",new JSONArray().put("@computer").put(legacyFolder).toString()).putString("app_folders",new JSONObject().put(legacyFolder,folder).toString()).putString("desktop_positions_portrait",new JSONObject().put(legacyFolder,new JSONObject().put("x",.4).put("y",50)).toString()).putString("desktop_positions_landscape",new JSONObject().put(legacyFolder,new JSONObject().put("x",.7).put("y",80)).toString()).putBoolean("desktop_v41",true).putBoolean("desktop_recycle_added",true).putBoolean("sidebar_visible",true).putBoolean("sidebar_portrait",true).putBoolean("sidebar_landscape",true).putString("gadgets",new JSONArray(Arrays.asList(GadgetCatalog.IDS)).toString()).putString("gadget_note","Keep my old gadget note").putInt("startup_mode",2).putBoolean("welcome_on_start",false).putBoolean("reduce_motion",true).putBoolean("taskbar_apps",false).commit();TenThemes.TEN.get(0).apply(store);
        getTargetContext().getSharedPreferences(StorageAccess.PREFS,0).edit().putBoolean("seen",true).commit();getTargetContext().getSharedPreferences(StartupExperience.SESSION,0).edit().putBoolean("seen",true).putBoolean("welcome_seen",true).putBoolean(StartupExperience.HOME_OFFERED,true).commit();
        home=(MainActivity)startActivitySync(new Intent(Intent.ACTION_MAIN).setComponent(new ComponentName(getTargetContext(),MainActivity.class)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));root=home.getWindow().getDecorView();await(()->TenSmoke.find(root,DesktopIconGrid.class)!=null,"Desktop ready");
        desktops();closedDesktopRecovery();rotation();palettes();recreation();
        result.putString("stream","PASS: upgraded Seven gadget flags cannot restore a sidebar in either orientation; legacy Desktop 1 folders and layouts preserved; new and existing secondary desktops have independent empty icon sheets; pin/group/layout isolation, desktop-close merge, multi-desktop folder recovery and validated backup roundtrip; live dark/light/Aero application content, dynamic controls, hidden windows, image/web preservation and recreation\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable e){try{shot("ten5-failure");}catch(Exception ignored){}result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
    TenDesktops manager(){try{Field f=MainActivity.class.getDeclaredField("tenDesktops");f.setAccessible(true);return(TenDesktops)f.get(home);}catch(Exception e){throw new RuntimeException(e);}}
    void desktops()throws Exception{
        ui(()->{check(store.desktop().equals(Arrays.asList("@computer",legacyFolder)),"Upgrade retains Desktop 1 icons");check(TenDesktopItems.positions(store,"portrait").optJSONObject(legacyFolder).optDouble("x")==.4,"Portrait layout migrated");check(TenDesktopItems.positions(store,"landscape").optJSONObject(legacyFolder).optDouble("x")==.7,"Landscape layout migrated");home.open("@notes");EditText note=(EditText)TenSmoke.description(windows().get("@notes"),"Notepad text");note.setText("Workspace theme test document");manager().select(other);check(store.desktop().isEmpty()&&windows().isEmpty(),"Existing secondary desktop starts empty");check(TenSmoke.find(root,DesktopIconGrid.class).getChildCount()==0,"Switch refreshes actual icon sheet");String created=manager().create();manager().select(created);check(store.desktop().isEmpty(),"New desktop starts empty");store.toggle("@browser");home.refreshTen();check(store.desktop().equals(Collections.singletonList("@browser")),"Pin belongs to current desktop");try{TenDesktopItems.positions(store,"portrait",new JSONObject().put("@browser",new JSONObject().put("x",.1).put("y",77)));}catch(JSONException e){throw new RuntimeException(e);}String grouped=store.createFolder("Only on this desktop",Collections.singletonList("@browser"));check(store.desktop().equals(Collections.singletonList(grouped)),"Grouping updates current sheet");manager().select(first);check(store.desktop().equals(Arrays.asList("@computer",legacyFolder)),"Other desktop folders do not leak");check(TenDesktopItems.positions(store,"portrait").optJSONObject(legacyFolder).optDouble("x")==.4,"Other desktop placement does not leak");check(manager().remove(created),"Can close secondary desktop");check(store.desktop().contains(grouped)&&store.folder(grouped)!=null,"Closing desktop retains its shortcuts and folder contents");});
        ui(()->{try{manager().select(other);store.desktop(Collections.singletonList(legacyFolder));JSONObject folder=store.folder(legacyFolder),places=store.folderPositions(legacyFolder);store.setRecycledFolder(legacyFolder,null,null);check(!store.isFolder(legacyFolder)&&!TenDesktopItems.items(store,first).contains(legacyFolder)&&store.desktop().isEmpty(),"Recycle removes folder references from every desktop");store.setRecycledFolder(legacyFolder,folder,places);check(store.desktop().contains(legacyFolder)&&TenDesktopItems.items(store,first).contains(legacyFolder),"Restore returns folder to both original desktops");store.desktop(Collections.emptyList());JSONObject snapshot=DesktopBackup.snapshot(store);DesktopBackup.Plan parsed=DesktopBackup.parse(snapshot.toString());check(parsed.values.containsKey(TenDesktopItems.KEY),"Backup includes all desktop icon sheets");JSONObject banks=new JSONObject((String)parsed.values.get(TenDesktopItems.KEY));check(banks.getJSONObject(first).getJSONArray("shortcuts").length()==3&&banks.getJSONObject(other).getJSONArray("shortcuts").length()==0,"Backup made on empty desktop retains Desktop 1");banks.getJSONObject(other).getJSONArray("shortcuts").put("folder:not-a-real-id");snapshot.getJSONObject("settings").getJSONObject(TenDesktopItems.KEY).put("value",banks.toString());boolean rejected=false;try{DesktopBackup.parse(snapshot.toString());}catch(JSONException expected){rejected=true;}check(rejected&&store.desktop().isEmpty(),"Invalid desktop bank rejected before mutation");manager().select(first);}catch(Exception e){throw new RuntimeException(e);}});
    }
    void closedDesktopRecovery()throws Exception{ui(()->{try{String retired=manager().create();manager().select(retired);String id=store.createFolder("Recover after desktop close",Collections.singletonList("@settings"));JSONObject folder=store.folder(id),places=store.folderPositions(id);store.setRecycledFolder(id,null,null);check(manager().remove(retired),"Close desktop after recycling a folder");store.setRecycledFolder(id,folder,places);check(store.desktop().contains(id)&&store.folderItems(id).equals(Collections.singletonList("@settings")),"Restore from a closed desktop stays reachable on the current desktop");}catch(Exception e){throw new RuntimeException(e);}});}
    void rotation()throws Exception{for(int orientation:new int[]{ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE,ActivityInfo.SCREEN_ORIENTATION_PORTRAIT}){ui(()->home.setRequestedOrientation(orientation));await(()->(root.getWidth()>root.getHeight())==(orientation==ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE),"Rotation settled");ui(()->check(TenSmoke.find(root,GadgetSidebar.class)==null&&TenSmoke.description(root,"Desktop floating gadgets")==null,"No gadget view attached after rotation"));}ui(()->{check(store.prefs.getString("gadget_note","").equals("Keep my old gadget note"),"Removal preserves old note data");manager().select(other);});await(()->TenSmoke.find(root,DesktopIconGrid.class).getChildCount()==0&&windows().isEmpty(),"Empty sheet is visible");android.os.SystemClock.sleep(650);shot("ten5-empty-desktop");ui(()->manager().select(first));}
    void palettes()throws Exception{
        ui(()->{home.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);home.open("@files");home.open("@calendar");home.open("@browser");home.open("@nota");home.open("@settings");((TenSettings)windows().get("@settings").body).navigate("colors");});await(()->root.getWidth()>root.getHeight(),"Landscape theme review");
        Map<String,DesktopWindow> before=new LinkedHashMap<>(windows());DesktopWindow note=before.get("@notes");EditText editor=(EditText)TenSmoke.description(note,"Notepad text");final int[] imageColor={0};final WebView web=TenSmoke.find(before.get("@browser").body,WebView.class);final android.graphics.drawable.Drawable webBackground=web==null?null:web.getBackground();
        ui(()->{editor.setSelection(3,9);TenThemes.TEN.get(2).apply(store);home.applyTenAppearance();for(DesktopWindow w:before.values()){check(windows().get(w.toolId)==w,"Theme preserves "+w.toolId);check(w.body.getBackground() instanceof ColorDrawable&&TenAppearance.luma(((ColorDrawable)w.body.getBackground()).getColor())<70,"Dark content in "+w.toolId);}check(editor.getSelectionStart()==3&&editor.getSelectionEnd()==9&&editor.getText().toString().equals("Workspace theme test document"),"Theme preserves note selection and document");check(TenAppearance.luma(editor.getCurrentTextColor())>200,"Notepad dark text contrast");check(web==null||web.getBackground()==webBackground,"Website background is not repainted");ImageView picture=new ImageView(home);picture.setBackgroundColor(0xfffefefe);TenAppearance.apply(picture);imageColor[0]=((ColorDrawable)picture.getBackground()).getColor();check(imageColor[0]==0xfffefefe,"Photo/image surfaces retain their colors");TextView dynamic=Aero.text(home,"Dynamic palette row",13,Aero.INK);dynamic.setContentDescription("Dynamic palette row");dynamic.setBackgroundColor(android.graphics.Color.WHITE);((TenSettings)before.get("@settings").body).body.addView(dynamic);});
        await(()->{View row=TenSmoke.description(root,"Dynamic palette row");return row instanceof TextView&&TenAppearance.luma(((TextView)row).getCurrentTextColor())>200&&TenAppearance.luma(((ColorDrawable)row.getBackground()).getColor())<70;},"New content inherits the selected palette");shot("ten5-dark-settings");
        ui(()->{home.open("@files");});shot("ten5-dark-explorer");ui(()->home.open("@run"));awaitSystem("Run command");shot("ten5-dark-run");systemClick("Cancel");
        ui(()->{try{JSONObject profile=ThemeProfiles.capture(store,"Dark apps fixture");JSONObject decoded=ThemeProfiles.unpack(home,new java.io.ByteArrayInputStream(ThemeProfiles.pack(home,profile)));check(decoded.getBoolean("ten_apps_dark"),"Portable theme retains app mode");TenThemes.TEN.get(1).apply(store);home.applyTenAppearance();for(DesktopWindow w:before.values())check(TenAppearance.luma(((ColorDrawable)w.body.getBackground()).getColor())>200,"Light content restored in "+w.toolId);check(TenAppearance.luma(editor.getCurrentTextColor())<90,"Note ink restored in light mode");check(editor.getSelectionStart()==3&&editor.getSelectionEnd()==9,"Selection survives light mode");}catch(Exception e){throw new RuntimeException(e);}});shot("ten5-light-explorer");
        ui(()->{TenThemes.AERO.get(2).apply(store);home.applyTenAppearance();home.open("@settings");((TenSettings)windows().get("@settings").body).navigate("themes");check(TenThemes.aero(store.prefs)&&!TenAppearance.dark(home),"Aero preset applies across apps");});shot("ten5-aero-apps");
        ui(()->{manager().select(other);home.open("@gadget:calculator");DesktopWindow hidden=windows().get("@gadget:calculator");manager().select(first);TenThemes.TEN.get(2).apply(store);home.applyTenAppearance();check(hidden.getVisibility()==View.GONE&&TenAppearance.luma(((ColorDrawable)hidden.body.getBackground()).getColor())<70,"Theme also reaches inactive-desktop windows");});
    }
    void recreation()throws Exception{ui(()->manager().select(other));final java.util.concurrent.BlockingQueue<MainActivity> resumed=new java.util.concurrent.LinkedBlockingQueue<>();Application app=(Application)getTargetContext().getApplicationContext();Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a instanceof MainActivity)resumed.offer((MainActivity)a);}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(lifecycle);ui(()->home.recreate());Activity activity=resumed.poll(15,java.util.concurrent.TimeUnit.SECONDS);app.unregisterActivityLifecycleCallbacks(lifecycle);check(activity instanceof MainActivity,"Activity recreated");home=(MainActivity)activity;root=home.getWindow().getDecorView();await(()->TenSmoke.find(root,DesktopIconGrid.class)!=null,"Restored desktop ready");ui(()->{check(manager().current().equals(other)&&store.desktop().isEmpty(),"Empty desktop persists through recreation");check(TenAppearance.dark(home),"App palette persists through recreation");manager().select(first);check(store.desktop().contains(legacyFolder)&&store.folderItems(legacyFolder).equals(Arrays.asList("@browser","@notes")),"Desktop 1 folder data survives recreation");TenThemes.TEN.get(0).apply(store);home.applyTenAppearance();});}
}
